/* אוצר מילים אמירם — 500 מילים (אנגלית/עברית + אסוציאציה). נוצר אוטומטית. */
const AMIRAM_WORDS = [{"e":"abandon","h":"לנטוש","a":["אבא בא דן ונטש את הבית","אבנדון - בן דון נטוש מהמשפחה"]},{"e":"abbreviate","h":"לקצר","a":["אברווייט את הטקסט - קצור וקצר","אבר בריבויט - קיצור הברות"]},{"e":"ability","h":"יכולת","a":["אביליטי - אבא לי יכולת גדולה","יכולת אביא לי בחיים"]},{"e":"abolish","h":"לביטול","a":["אבוליש - לא ביטלו את החוק","אבוליש - בוא נביטל את זה"]},{"e":"abrupt","h":"פתאומי","a":["אברפט - אב ראפט את הדלת פתאומי","פתאום רופט את הקשר"]},{"e":"absent","h":"נעדר","a":["אבסנט - אבא סנט היה נעדר","סנט אבסנט - נעדר מכאן"]},{"e":"absolute","h":"מוחלט","a":["אבסוליוט - אב סולוט מוחלט בדעתו","סולוט אבסוליוט - ללא פשרה"]},{"e":"abstract","h":"מופשט","a":["אבסטרקט - אב סטרק את הרעיון למופשט","טרק אבסטרקט - רחוק ומופשט"]},{"e":"absurd","h":"אבסורדי","a":["אבסורד - אב סורד את זה אבסורדי","סורד אבסורד - לא הגיוני"]},{"e":"abundant","h":"שופע","a":["אבונדנט - אב עם דנט שופע בעוד","בונדנט - דנדנה שופעת"]},{"e":"accelerate","h":"להאיץ","a":["אקסלרייט - קס לרייט את הגז להאיץ","קס לרייט - זרז את הדרך"]},{"e":"accent","h":"הבטה","a":["אקסנט - קס נט את ההבטה בדבור","נט קס - הטיית הגה"]},{"e":"access","h":"גישה","a":["אקסס - קס ים - גישה לים","קס ים - נתיב פתוח"]},{"e":"accommodate","h":"להכיל","a":["אקומודייט - קום אוד ייט - להכיל הרבה אורחים","קום דיי ט - בן הבית מכניס"]},{"e":"accompany","h":"ללוות","a":["אקומפני - קום פן יא - ללוות כמי שבא לפנייה","קום פן - לוות בנאמנות"]},{"e":"accomplish","h":"להשיג","a":["אקומפליש - קום פלישׁ - להשיג ולסיים","קום פליש - ביצוע יפה"]},{"e":"accumulate","h":"להצטבר","a":["אקומיולייט - קום יול יט - להצטבר ויול","קום יול - צובר עם הזמן"]},{"e":"accurate","h":"מדויק","a":["אקיורייט - קיור יט - מדויק כמו רפואה","קיור יט - נכון לגמרי"]},{"e":"accuse","h":"להאשים","a":["אקיוז - קיוז - להאשים כמו קול צורח","קיוז - קול האשמה"]},{"e":"achieve","h":"להצליח","a":["אצ'יב - צ'יב - להצליח עם תחכום","אתשיב - תשובה על הצלחה"]},{"e":"acknowledge","h":"להודות","a":["אקנוליג' - קנו ליג' - להודות שניצחו","קנו - הכיר וזיכר"]},{"e":"acquire","h":"לרכוש","a":["אקוואיר - קו וויר להשנות - לרכוש כל יום","קו ויר - קו רכישה ישר"]},{"e":"adapt","h":"להסתגל","a":["אדאפט - אדם אדמ טס - להסתגל למקום חדש","דאפט - לעדף הסתגלות"]},{"e":"adequate","h":"הולם","a":["אדיקוויט - אדי קוויט - הולם וכדי לתת","אדי קו - די טוב ודיי"]},{"e":"adhere","h":"להיצמד","a":["אדהיר - אד היר - להיצמד כמו דבק","אדהיר - הדבקה בעמדה"]},{"e":"adjacent","h":"סמוך","a":["adjacent - הצליל 'a-day' כמו 'אני ליד', הדברים הסמוכים הם זה ליד זה.","בגשת 'adi' - שני דברים סמוכים הם בקרבה אלה לאלה, כמעט מתגעים."]},{"e":"adjust","h":"לכיוונון","a":["adjust - 'א-דג'עסט' כמו 'אני דוגש את הפרטים', כיוונון הוא התאמה דקה.","dj שברצפט מ-'דק', כיוונון דק ודייק של הפרטים."]},{"e":"administer","h":"לנהל","a":["administer - 'אד-מיניסטר' כמו 'אד מנהל את כל העניינים כאן.","minister = מנהיג, administer = הנהלה, מי שנותן ניהול."]},{"e":"admire","h":"להעריץ","a":["admire - 'אד-מיר' כמו 'אדם יראה ויהעריץ את היופי הזה.","mir = ראה, admire = מי שרואה ומעריץ את היופי."]},{"e":"admit","h":"להכיר בחובה","a":["admit - 'אד-מיט' כמו 'אדם מיט (מודה) בחובה בכנות.","mit = משהו כתוב, admit = אני מודה ומכיר בכתב."]},{"e":"adopt","h":"לאמץ","a":["adopt - 'אה-דופט' כמו 'אה דופק - לקח את הילד וכעת הוא שלי לאמץ.","דופ מרמז על 'דופק', לאמץ זה לקחת דופק של משפחה."]},{"e":"advance","h":"להתקדם","a":["advance - 'אד-וונס' כמו 'אד ואנחנו קדימה להתקדם.","וונס = פעם, advance = התקדמות אחת כחלק מתהליך."]},{"e":"adverse","h":"שלילי/מזיק","a":["adverse - 'אד-וורס' כמו 'אד, זה וורס (גרוע), שלילי ומזיק לנו.","וורס = גרוע, adverse = הוא שלילי וגרוע מאוד."]},{"e":"advocate","h":"לתמוך/להוביל","a":["advocate - 'אד-וו-קייט' כמו 'אדם וו קייט תומכת בזכויות, היא מתומכת.","קייט יוצאת להוביל, advocate = להוביל ולתמוך."]},{"e":"aesthetic","h":"אסתטי/יפה","a":["aesthetic - 'אס-תטיק' כמו 'אס תטיק - זה יפה וגם סתטי מאוד.","תטיק = טיק, זה הריתמוס של היופי האסתטי."]},{"e":"affect","h":"להשפיע","a":["affect - 'אה-פקט' כמו 'אה פקט - זה משפיע על הפקט שלנו.","פקט = עובדה, זה משנה את העובדה."]},{"e":"affiliate","h":"להצטרף","a":["affiliate - 'אה-פיל-יאייט' כמו 'אה פילה את עצמה, הצטרפה לקבוצה.","פיל = חייבר, affiliate = מצטרף לרשת חברים."]},{"e":"affirm","h":"לאשר","a":["affirm - 'אה-פרם' כמו 'אה פרם - זה חוק קבוע, אני מאשר!","פרם = קבוע, affirm = אני קובע וממאיר את זה."]},{"e":"afford","h":"להעות","a":["afford - 'אה-פורד' כמו 'אה פורד - אני יכול להחזיק בעלות הזה.","פורד = כוח, afford = יש לי כוח וכושר להעות."]},{"e":"aggregate","h":"לצבור/סכום","a":["aggregate - 'אג-רגאייט' כמו 'אגרגים - אני אוספר אותם לצבור סכום.","אגרג = מערכה, aggregate = צבור וסכום של הכל."]},{"e":"aggravate","h":"להחמיר","a":["aggravate - 'אג-רייווייט' כמו 'אגרייו את זה - עכשיו זה חמור יותר.","גרייו = קשה, aggravate = החמרתי, עשיתי קשה יותר."]},{"e":"agile","h":"זריז/מהיר","a":["agile - 'אג-ייל' כמו 'אניל וזריז מאוד, אני זריז כמו נצנוץ.","ייל = מהר, agile = אני זריז ומהיר כמו אדם צעיר."]},{"e":"alleviate","h":"להקל","a":["alleviate - 'אל-לי-ווייט' כמו 'אל לי וויט - תן לי הקלה מהצרה.","לי = לי, alleviate = הקל לי ממה שכואב."]},{"e":"allocate","h":"להקצות","a":["allocate - 'אל-לו-קייט' כמו 'אל לו קיט - הקצה לו חלק מהעוגה.","קייט = קצוות, allocate = קצה לכל אחד את החלק שלו."]},{"e":"alter","h":"לשנות","a":["alter - 'אול-טר' כמו 'אולטר - זה שונה, אני שינויתי את זה.","טר = טריק, alter = טריק של שינוי."]},{"e":"alternative","h":"חלופה","a":["alternative - 'אול-טרנטיו' כמו 'אולטר נתיוו - דרך שונה, חלופה אחרת.","טרנ = טור, alternative = טור שני, חלופה."]},{"e":"ambiguous","h":"עמום","a":["ambiguous - 'אם-ביג-יואס' כמו 'אם זה ביג - זה עמום וגדול מדי להבנה.","ביג = גדול, ambiguous = גדול מדי כדי להבין בבירור."]},{"e":"amend","h":"לתקן","a":["amend - 'אה-מנד' כמו 'אה מנד - זה מתוקן, אני תקנתי את זה.","מנד = מודה, amend = אני מודה וגם מתקן את הטעות."]},{"e":"ample","h":"רחב","a":["ample - 'אם-פל' כמו 'אמפל - הרבה מאוד, רחב וגדול.","פל = פעם, ample = הרבה פעמים, המון, רחב."]},{"e":"amplify","h":"להגביר","a":["amplify - 'אם-פלי-פיי' כמו 'אמפלי פיי - הגברתי את הקול המוזיקלי.","פלי = פלא, amplify = פלא של הגברה, הגברתי הרבה."]},{"e":"analyze","h":"לנתח","a":["אנא לייז את הנתונים - אנו צריכים לנתח כל פרט.","עם ניתוח (ANALYZE) מעמיק נוכל לנתח את הבעיה."]},{"e":"ancestor","h":"אבא קדום","a":["אנסטור שלי היה אבא קדום מימי קדם.","אנסטור מלמד אותנו שהאבא הקדום היה חזק."]},{"e":"ancient","h":"עתיק","a":["בימים עתיקים (ANCIENT) היו אנשים עתיקים וחוכמים.","אנשיינט היו העיר העתיקה במצרים עתיקה."]},{"e":"annex","h":"להצמיד","a":["אנקס את הנייר להצמיד אותו לקובץ.","כשתאנקס (ANNEX) את הטריטוריה תצמיד אותה אליך."]},{"e":"annotate","h":"להוסיף הערות","a":["אנוטיישן היא הערה שמוסיפים להוסיף הערות.","כשאתה אנוטייט (ANNOTATE) אתה מוסיף הערות בטקסט."]},{"e":"announce","h":"להודיע","a":["אנאונס לעם - הודעה חדשה להודיע בחיוך.","כשאנאונסים (ANNOUNCE) משהו אתה מודיע לכולם בגלוי."]},{"e":"anonymous","h":"אנונימי","a":["אנונימי - אנו לא יודעים מי הוא, שמו אנונימי.","כשאתה אנונימוס (ANONYMOUS) אף אחד לא יודע מי אתה."]},{"e":"anticipate","h":"לצפות","a":["אנטיסיפ - צפה לעתיד שמתקרב, כצפוי לצפות בסכנה.","כשאתה מאנטיסיפיט (ANTICIPATE) אתה צופה בעתיד ומוכן."]},{"e":"anxiety","h":"חרדה","a":["אנקסיטי - חרדה גוברת כשהלב צופץ מחרדה.","כל אנקסיוס (ANXIETY) מוליד חרדה עמוקה בנפש."]},{"e":"apathy","h":"אדישות","a":["אפתיה היא אדישות מוחלטת, לא כובדים לאחר.","כשיש אפתי (APATHY) אתה אדיש וחסר רגש."]},{"e":"apparent","h":"ברור","a":["אפרנט - וברור לעיניים שהכל נראה ברור.","כשזה אפרנט (APPARENT) הכל ברור וגלוי לעיניים."]},{"e":"appeal","h":"ערעור","a":["אפיל לבית המשפט - ערעור על ההחלטה הלא צודקת.","כשאתה אפיליים (APPEAL) אתה מגיש ערעור על הפסק דין."]},{"e":"append","h":"להוסיף","a":["אפנד את הנייר ספר - הוסף הוסיף את העמודים.","כשאתה אפנד (APPEND) אתה מוסיף דברים בסוף הרשימה."]},{"e":"applaud","h":"לתשא כפיים","a":["אפלוד - כפיים משמעו לתשא כפיים בשמחה.","כשאנשים אפלוד (APPLAUD) הם תוששים כפיים בהתלהבות."]},{"e":"apply","h":"להגיש בקשה","a":["אפלאי לעבודה - הגשת בקשה כדי להגיש בקשה.","כשאתה אפלאיי (APPLY) אתה מגיש בקשה לעבודה."]},{"e":"appoint","h":"למנות","a":["אפוינט מנהל - מנית אותו בפורמליות למנות.","כשמנויים אפוינט (APPOINT) אתה מונה לתפקיד משמעותי."]},{"e":"appreciate","h":"להעריך","a":["אפרישייט את המתנה - הערכה עמוקה כדי להעריך.","כשאתה מאפרישיט (APPRECIATE) אתה מעריך ומודה מעמקי לב."]},{"e":"approach","h":"להתקרב","a":["אפרוץ' לחבר - התקרבות הדרגתית להתקרב בעדינות.","כשאתה אפרוצ'ים (APPROACH) אתה מתקרב אט אט בזהירות."]},{"e":"appropriate","h":"הולם","a":["אפרופריאט דברים - הולם וראוי לענין הולם.","כשזה אפרופריאט (APPROPRIATE) זה הולם ומתאים לתנאים."]},{"e":"approve","h":"לאשר","a":["אפרוב הצעה - אשרור רשמי כדי לאשר החלטה.","כשמנהל אפרובס (APPROVE) הוא מאשר את הבקשה רשמית."]},{"e":"approximate","h":"בקירוב","a":["אפרוקסימטלי עשר איש - בקירוב משוער לא בדיוק.","כשאתה מאומד אפרוקסימטלי (APPROXIMATE) זה בקירוב בלבד."]},{"e":"arbitrary","h":"שרירותי","a":["ארביטרארי החלטה - שרירותית בלי הגיון או הצדקה.","כשמישהו עושה בחירה ארביטרארי (ARBITRARY) היא שרירותית לגמרי."]},{"e":"archaic","h":"עתיק יומין","a":["ארכייק - עתיק יומין כמו לשון עתיקה מימי קדם.","כשמילה היא ארכיאיק (ARCHAIC) היא עתיקה יומין ולא בשימוש."]},{"e":"arise","h":"להתעורר","a":["אריז מהשינה - התעוררות בבוקר להתעורר מיד.","כשאתה אריאז (ARISE) אתה מתעורר ועולה בדעתך."]},{"e":"arrogant","h":"גאה","a":["אראגנט אדם - גאה ויהיר, ביטחון עצמי מופרז.","כשאדם הוא אראגנט (ARROGANT) הוא גאה וזלול דעה על עצמו."]},{"e":"articulate","h":"ברור בדיבור","a":["ארטיקולציה - אומר בבירור טוב, ברור בדיבור כשאני מדקדק בכל מילה.","כשמדברים בצורה ארטיקולטיבית, הדיבור הוא ברור וקל להבנה."]},{"e":"aspect","h":"היבט","a":["אספקט - כל זווית וכל היבט של הנושא חשוב לשיקול.","כשמסתכלים על כל אספקט (היבט) של הבעיה, מוצאים את הפתרון."]},{"e":"aspire","h":"לשאוף","a":["אספייר - כשאתה שואף וחלמת גבוה, אתה חתום לשאיפה גדולה.","אני אספייר להיות מוצלח, כי אני שואף ללא הגבלות."]},{"e":"assemble","h":"להתאסף","a":["אסמבל - כשכולם מתכנסים והולכים להתאסף, זה אסמבלי מושלם.","אסמבלה של אנשים מתכנסת כדי להתאסף למפעל משותף."]},{"e":"assert","h":"לטעון","a":["אסרט - כשאתה אומר עם כוח וטוען דברים, אתה מטעין בצורה חזקה.","הוא טוען בתוקף ומטעין את דבריו בכוח, כן אסרט זה לטעון."]},{"e":"assess","h":"להעריך","a":["אסס - כשאתה מעריך וסוקר דברים בקפידה, אתה עורך הערכה מדקדקת.","לפני שמחליטים, צריך אסס (להעריך) את כל הפרטים."]},{"e":"assign","h":"להקצות","a":["אסיין - כשמקצים משימה לאחד, אתה מהקצה אותה בדיוק אליו.","המנהל יאסיין (יקצה) לך עבודה חדשה כל יום."]},{"e":"assist","h":"לעזור","a":["אסיסט - כשאתה עוזר לחבר שלך, אתה אסיסט נאמן בעזרה.","כשצריך עזרה, הוא תמיד יאסיסט (יעזור) לי בשמחה."]},{"e":"associate","h":"להשתייך","a":["אסוסיאט - כשמתחברים לקבוצה מסוימת, אתה מתחייב להשתייך אליה.","בעסק הזה אני אסוסיאט (משתייך) למשפחת העובדים."]},{"e":"assume","h":"להניח","a":["אסיום - כשמניחים משהו כנכון, אתה מניח הנחה שלא בדקת.","אני אסיום (מניח) שאתה בן 30, אבל זה רק הנחה שלי."]},{"e":"assure","h":"להשביע עין","a":["אשוור - כשמשביעים עין ומבטיחים משהו, אתה משביע עין בעוצמה.","המוכר אשוור (השביע עיניים) שהמוצר אמיתי וטוב."]},{"e":"astonish","h":"להדהים","a":["אסטוניש - כשמדהימים את מישהו, הוא נדהם לגמרי כשם האנגלית.","התעלול היפה אסטוניש (הדהים) את כל הילדים בהפתעה."]},{"e":"attain","h":"להשיג","a":["אטיין - כשמגיעים להשיג מטרה, אתה אטיין (משיג) אותה בתאונה.","דרך עמל וקשיות אני אטיין (אשיג) את חלומי הגדולים."]},{"e":"attempt","h":"לנסות","a":["אטמפט - כשמנסים לעשות משהו, אתה אטמפטים (מנסה) שוב ושוב.","בכל אטמפט (נסיון) אני נכשל, אבל אנסה שוב מחר."]},{"e":"attend","h":"להשתתף","a":["אטנד - כשמשתתפים בחתונה, אתה אטנדינג (משתתף) בעם רבים.","הוא אטנד (השתתף) בכל הישיבות החשובות בחברה."]},{"e":"attribute","h":"תכונה","a":["אטריביוט - כל תכונה טובה שיש לך, זו אטריביוט מיוחדת שלך.","כשיש לך אטריביוטים (תכונות) טובות, אתה בן אדם טוב."]},{"e":"audible","h":"שניתן לשמוע","a":["אודיבל - כשמשהו שניתן לשמוע ברור, זה אודיבל כמו צליל ברור.","הקול שלו כל כך אודיבל (שניתן לשמוע) שגם מרחוק שומעים."]},{"e":"augment","h":"להגביר","a":["אוגמנט - כשמגבירים את הכמות, אתה מוגמנט (מגביר) אותה בהרבה.","כשמוסיפים גבוהות, אתה אוגמנט (מגביר) את ההשפעה."]},{"e":"authentic","h":"אמיתי","a":["אותנטיק - כשמשהו אמיתי ולא זיוף, זה אותנטיק באמת למדי.","הזהב האותנטיק (האמיתי) מבריק יותר מהזיוף."]},{"e":"authorize","h":"להיתן הרשות","a":["אוטוריז - כשנותנים הרשות ועומדים בסמכות, אתה אוטוריזד (מורשה).","רק המנהל יכול לאוטוריז (להתן הרשות) את החיתום הזה."]},{"e":"available","h":"זמין","a":["אוויילבל - כשמשהו זמין ותוכל לקנות אותו, זה אוויילבל (זמין) עכשיו.","המוצר כבר אוויילבל (זמין) בחנות כמו שנדרש."]},{"e":"avoid","h":"להימנע","a":["אווויד - כשמימנעים מדברים שליליים, אתה אווויד (נמנע) מהם בזריזות.","אני אווויד (נמנע) מפגישה עם אנשים רעים ומתגוננים."]},{"e":"aware","h":"מודע","a":["אוור - כשמודעים למשהו סביבך, אתה אוור (מודע) לכל צעד.","היה צריך להיות אוור (מודע) לחשש לפני שקרה הקלקול."]},{"e":"awkward","h":"מביך","a":["אוקוורד - כשמשהו מביך וקשה, זה אוקוורד (מביך) מכל הבחינות.","הדברים המביכים הם אוקוורד (מביך) ולא יפים בעיניים."]},{"e":"ban","h":"להוציא חוק","a":["בן - כשהוציאו חוק להוציא חוק, אתה בן (מוציא חוק) את ההחלטה.","הממשלה בנה חוק שמוציאה חוק על הרעם הזה."]},{"e":"barely","h":"בקושי","a":["בקושי בירלי - קרוב לכ-אפס, קשה מאוד להבחין","בר בקושי - הסרגל בטוים עדין בקושי נראה"]},{"e":"barren","h":"שומם","a":["בארן שומם - הפקר בר אבן שומם ללא חיים","בר ריק, בר כלום - שדה פוקד בארן לחלוטין שומם"]},{"e":"barrier","h":"מחסום","a":["בריאר מחסום - בריא בעד דלת, מחסום עוצר אותך","בר אי - בר קבע, מחסום מפריד בין שני צדים"]},{"e":"basic","h":"בסיסי","a":["בייסיק בסיס - הבסיס של כל דבר הוא בסיסי","בסיס אתה - לבסיס כל דבר צריך להתחיל"]},{"e":"behalf","h":"בשם","a":["בהלף בשם - בעצם בהלף משמעו במקום של איש","בשם של הקבוצה - בהלף הוא למען ובשם של כולנו"]},{"e":"believe","h":"להאמין","a":["בליב לאמין - אני בליב כלומר מאמין בלבי","להאמין בלב - בליב בלבבך תאמין בכל הלב"]},{"e":"benefit","h":"תועלת","a":["בנפיט תועלת - תועלת היא הרווח שלך מהעסקה","נפע טוב - כל סעיף מוביל תועלת ויתרון"]},{"e":"bias","h":"הטיה","a":["ביאס הטיה - הטיה היא סטייה משלווי משקל","ביאים טיה - כשהטיה קיימת אתה סט בצד אחד"]},{"e":"bind","h":"לקשור","a":["בינד קשור - בינד זה לקשור היצורים","קשור בינדים - כל קשר מחברת דברים יחדיו"]},{"e":"blame","h":"להאשים","a":["בליים להאשים - להאשים את בן זוגך בקול רם","האשמה בלם - כשמאשימים, הפה וודיע ופלט דברים"]},{"e":"boost","h":"לעלות","a":["בוסט לעלות - בוסט משאבת את הערך למעלה","עלייה בוסט - כשתעלה בבוסט, תגדל ותרחק"]},{"e":"bound","h":"גבול","a":["באונד גבול - גבול זה קו שמקיף את האזור","בסמוך בגבול - כל גבול אתה מוקף בו"]},{"e":"brief","h":"קצר","a":["בריף קצר - בריף קצר כמו תקציר קצר","קצר בריף - דברים קצרים וקוצים נקראים בריף"]},{"e":"brilliant","h":"זוהר","a":["בריליאנט זוהר - בריליאנט כמו היהלום שזוהר","זהור בריליאנטי - כל בריליאנט מאיר בזוהר עז"]},{"e":"brisk","h":"זריז","a":["בריסק זריז - בריסק הוא הליכה זריזה וחדה","זריז ובריסק - כשתלך בריסק תנוע בעז וזריזות"]},{"e":"broad","h":"רחב","a":["ברוד רחב - ברוד רחב כמו הכביש הרחב","רחב ברוד - כל ברוד פורש במרחב רחב"]},{"e":"calculate","h":"לחשב","a":["חשב כלכולייט - כאלולט אתה חושב וחוש״ב","לחשב כלקולייצ - חישוב זה דרך הלוגיקה למצאות"]},{"e":"campaign","h":"קמפיין","a":["קמפיין לקמפיין - קמפיין קול וקום, קול קמוט","לקמפיין קמפיין - קמפיין זה תנועה מסודרת וחוקית"]},{"e":"capacity","h":"יכולת","a":["קפה סיטי יכולת - קפה בתוך הסיטי, יכולת שתיה","יכולת קפה - סיטי זה צומצום, יכולת מוגבלת"]},{"e":"capture","h":"לתפוס","a":["קפטור תפוס - קפטור תופס בתוך הרשת","לתפוס קפטור - כשתקפטור, אתה תופס את החזון"]},{"e":"casual","h":"בדלוקי","a":["קזואל בדלוקי - קז־ואל כמו קז קל ובדלוקי","בדלוקי קזואל - בדלוקי זה קל וקז אל תופס"]},{"e":"cease","h":"הפסיק","a":["סיז הפסיק - סיז זה עצור, הפסיק כל דבר","הפסיק סיז - כשאתה סיז, הפסקת ממש הכל"]},{"e":"celebrate","h":"חגג","a":["סלברייט חגג - סלברייט כמו סלה וברית, בחוג","חגגנו סלברייט - כל אחד סלברייט מחוגג בעלצה"]},{"e":"certain","h":"בטוח","a":["סרטן בטוח - סרטן קבוע וודאי וטוח בדרך","בטוח סרטיין - סרטיין זה ודאות, בטחון מוחלט"]},{"e":"challenge","h":"אתגר","a":["צ׳לנג אתגר - צ׳לנג זה קול זריז של אתגר","אתגר צ׳לנג - כל צ׳לנג יוצר אתגר ומועד"]},{"e":"change","h":"שינוי","a":["צ'יינג' - שינוי הצליל, שינוי החיים","החיים משתנים כשנעים מ'chain' (שרשרת) ל'change' (שינוי)"]},{"e":"characteristic","h":"תכונה","a":["כרקטריסטיק - תכונה מאפיינת","character (אופי) וכל אחד בעל תכונות ייחודיות"]},{"e":"charge","h":"חיוב","a":["צ'ארג' - אני חייב לשלם, זה חיוב","על הקרטיס חיוב גדול של 'charge'"]},{"e":"chart","h":"תרשים","a":["צ'ארט - תרשים מראה את הדרך","על הגרף (chart) אתה רואה את התמונה"]},{"e":"chase","h":"רדף","a":["צ'ייס - רדפתי אחריו, צייד רדוף","הכלב רודף (chasing) את הביצים בחצר"]},{"e":"cherish","h":"יקר","a":["צ'ריש - אני יקר את זה כמו צרור ציבור","את מי שאתה אוהב ויקר לך, אתה חוזק (cherish)"]},{"e":"choice","h":"בחירה","a":["צ'ויס - בחירה בין דברים חלופיים","כשבוחרים (choice) בין אפשרויות צריך להחליט"]},{"e":"chronic","h":"כרוני","a":["כרוניק - מחלה כרונית היא עתיקה וארוכה","הכרוניקה (chronicle) מספרת על זמן ארוך"]},{"e":"circle","h":"עיגול","a":["סרקל - עיגול חוזר על עצמו בצו","סרקל באנגלית סובב וחוזר כמו עיגול"]},{"e":"cite","h":"צטט","a":["סייט - אני מצטט את הפרק, כתובת הספר","citation (ציטוט) משהו מגוף הטקסט"]},{"e":"civil","h":"אזרחי","a":["סיוויל - אזרחי הוא חברה, ציוויליות","civic ו civil קשורים לחברה אזרחית"]},{"e":"clarify","h":"הבהיר","a":["קלאריפיי - להבהיר את התמונה בבהירות","clarity (בהירות) וclarify (הבהרה) הם בני דודים"]},{"e":"clash","h":"התנגשות","a":["קלאש - התנגשות קולית חריפה","klash בעברית זה כשדברים נתקלים בחוזקה"]},{"e":"classify","h":"סיווג","a":["קלאסיפיי - לסווג את הדברים לסדר","class (מחלקה) וclassify (סיווג) קשורים"]},{"e":"clause","h":"סעיף","a":["קלוז - בסעיף זה כתוב משהו חשוב","clause (סעיף) במשפט משמעותי וסגור"]},{"e":"clean","h":"נקי","a":["קלין - נקי זה ללא כתם ולא מלוכלך","clean (נקי) בעברית קל להגיד וברור"]},{"e":"clear","h":"ברור","a":["קליר - ברור כמו קול גבוה וצלול","clear (ברור) צליל צלול וקליר"]},{"e":"climax","h":"שיא","a":["קלימקס - שיא ההתרגשות בפסגה","climax (שיא) הוא הנקודה הגבוהה ביותר"]},{"e":"cling","h":"נצמד","a":["קלינג - נצמדתי אליו בחוזקה","cling (נצמד) אתה תופס וחוזק לדבר"]},{"e":"cluster","h":"אשכול","a":["קלסטר - אשכול של דברים צמודים","cluster (אשכול) דברים מקובצים ביחד"]},{"e":"coarse","h":"גס","a":["קורס - גס כמו משטח גס ושונה","coarse (גס) קול קשה וגס"]},{"e":"coherent","h":"קוהרנטי","a":["קוהירנט - קוהרנטי זה יציב וקשור","coherent (קוהרנטי) כל חלק צמוד לשני"]},{"e":"collaborate","h":"שיתוף פעולה","a":["קולבוריט - שיתוף פעולה בעבודה משותפת","collaborate (שיתוף) כולם עובדים ביחד"]},{"e":"collapse","h":"קריסה","a":["קולאפס - קריסה מידית וחומרה","collapse (קריסה) הכל קורס בבת אחת"]},{"e":"colleague","h":"עמית","a":["קליג - עמית בעבודה היא חבר שלך","colleague (עמית) אנשים שעובדים ביחד"]},{"e":"collect","h":"אסוף","a":["כולקט - אסוף את כל הדברים הקטנים.","קולקציה שלמה נאספת בזהירות."]},{"e":"collide","h":"התנגש","a":["קול-היד - קול רועם כשמעצמות מתנגשות.","שני כדורים מתנגשים בקול חזק."]},{"e":"column","h":"עמודה","a":["קול-מן - עמודה של קול עומדת במרכז.","עמודת האבן עמדה כקול אתר."]},{"e":"combat","h":"קרב","a":["קומבט - קרב קום אל הקדמה.","לחימה אלימה בקום על היריב."]},{"e":"combine","h":"שלב","a":["קום-באיין - שלב מספר קום באיחוד.","שלבים מרובים מתאחדים ביחד."]},{"e":"comfortable","h":"נוח","a":["קומפורטבל - נוח כמו כומפה פורטבל.","כורסה קומפטית ונוחה מאוד."]},{"e":"command","h":"פקודה","a":["קום-אנד - פקודה שנשמעת קום אנד הנה.","קום כאן זו הפקודה החזקה."]},{"e":"commence","h":"התחיל","a":["קום-מנס - התחלה בקום מנסים שוב.","קום מנסים להתחיל מיד."]},{"e":"comment","h":"הערה","a":["קום-אנט - הערה קטנה כמו נמלה קומנט.","קול נמלה שהערה בד קט."]},{"e":"commit","h":"התחייב","a":["קום-מיט - התחייבות קום תמיד מיט.","מיט אחד עם קום בהתחייבות."]},{"e":"common","h":"נפוץ","a":["קומון - נפוץ כמו קול מון ברחוב.","מון רגיל ונפוץ בעולם."]},{"e":"communicate","h":"תקשר","a":["קום-יונו-קייט - תקשור קום יחידו קייט.","קייט מדברת וקום תקשר ביחד."]},{"e":"community","h":"קהילה","a":["קום-יונו-טי - קהילה של קום יחד טי.","טי חם בקהילת קום קרובה."]},{"e":"compact","h":"קומפקטי","a":["קום-פקט - קומפקטי כמו פקט קום.","קום דחוס וקומפקטי מאוד."]},{"e":"compare","h":"השווה","a":["קום-פיר - השווה את קום לפיר.","פיר עם קום משווה במדויק."]},{"e":"compassion","h":"חמלה","a":["קום-פישן - חמלה קום פשן רועמת.","פשן קום יוצר חמלה עמוקה."]},{"e":"compel","h":"הכריח","a":["קום-פל - הכריח בקום פל מטה.","פל קום מכריח בכוח גדול."]},{"e":"compensate","h":"פיצה","a":["קום-פנסייט - פיצוי קום פנסה אתה.","אתה קום פנסה זקוק פיצוי."]},{"e":"compete","h":"התחרות","a":["קום-פיט - התחרות קום באתה פיט.","פיט קום מתחרה בכל מרוץ."]},{"e":"compile","h":"הרכיב","a":["קום-פיל - הרכיב קום פיל קודם.","פיל קום מרכיב בזהירות רבה."]},{"e":"complain","h":"התלונן","a":["קום-פליין - התלונן קום פלן יום.","פלן קום התלונן בקול גבוה."]},{"e":"complement","h":"השלמה","a":["קום-פלימנט - השלמה קום פלמנט.","פלמנט קום משלים בהרמוניה."]},{"e":"complete","h":"השלים","a":["קום-פליט - השלים קום פליט מהיר.","פליט קום השלים הכל בזריזות."]},{"e":"complex","h":"מסובך","a":["קום-פלקס - מסובך קום פלקס מאוד.","פלקס קום היה מסובך מדי."]},{"e":"comply","h":"ציית","a":["קום-פליי - ציית קום פליי בנאמנות.","פליי קום מציית לפקודה תמיד."]},{"e":"component","h":"רכיב","a":["קום-פ-וננט - כל חלק קומי בהרכבה הוא רכיב חשוב.","קומפ בחברה - כל רכיב ברכיב גדול יותר קיים."]},{"e":"compose","h":"החבר","a":["קום-פ-וז - קום פה עם זה כדי להחבר את השירים.","קומפוז'ה - הרכבת מוזיקה היא החברת נתונים לקול."]},{"e":"comprehend","h":"הבין","a":["קום-פ-ריהנד - כל קום בראש לא יוביל להבנה אם לא תיכנס.","קומפרהנד - למה לא קומפרנד? כי לא הבנת!"]},{"e":"comprehensive","h":"מקיף","a":["קום-פ-ריהנסיב - קום לקחת את הכל, כל דבר מקיף בתוך קום.","קומפ כל דבר סיווג - זה מקיף הכל בחקירה שלמה."]},{"e":"compress","h":"דחס","a":["קום-פ-רס - קום וקח את הפ'ס (החלקים) וּדחסם ביחד.","קומפרס דחוס - אם קומפרסי את האוויר הוא הופך דחוס."]},{"e":"comprise","h":"להרכיב","a":["קום-פ-ריי זנאי - קום עם הפריים והרכב את הרכיבים.","קומפריי זה - כל קום פריים דבר להרכיב בתוכו."]},{"e":"compromise","h":"להתפשר","a":["קום-פ-ריי מיי - קום שם בעד מיי להתפשר על הדרך.","קומפ רומיי - קום רומנטי להתפשר יחד במחוזות."]},{"e":"compulsory","h":"חובה","a":["קום-פ-אל-סורי - קום פה וזה חובה לציית הסורי.","קומפ אלסורי - חובה קשוחה ישר כמו קום פה עכשיו!"]},{"e":"compute","h":"לחשב","a":["קום-פ-יוט - קום מחשבה שלמה בקום קומה כולה לחשב.","קומפיוט חישובים - קום פיוטי מחשבות זה לחשב מהר."]},{"e":"conceal","h":"להסתיר","a":["קום-סיל - קום סירו את הסוד בתוכך וְהסתר אותו.","קונסיל להסתיר - קום נסתר בסיר מתוך הסתרה טובה."]},{"e":"concede","h":"להודות","a":["קום-סיד - קום סיד ארץ, הודה שעשיתי את זה.","קונסיד מעלה - קום כל סיד בצד הזה של הודאה."]},{"e":"conceive","h":"להעלות בדמיון","a":["קום-סיו - קום עיני וראה בדמיון זה כל תמונה.","קונסיו עלה - קום סיוו בדעתך כל קונספט חדש."]},{"e":"concentrate","h":"להתרכז","a":["קום-סנ-טריט - קום סנטר התרכזות בכל קום שלנו ריק.","קונסנטריט - קום סנטר אתה בחושך כדי להתרכז טוב."]},{"e":"concept","h":"קונספט","a":["קום-סנ-פט - קום סנ בקונספט זה כל עיקרון קטן.","קונסנפט ניתוח - קום סנ פט רעיון מושכל ותקף."]},{"e":"concern","h":"דאגה","a":["קום-סרן - קום סר דאגות בתוך קום קטן.","קונסרן - קום סר אנחה זה דאגה גדולה שלך."]},{"e":"concert","h":"קונצרט","a":["קום-סרט - קום סר צאצא קונצרט מוזיקלי ומדהים.","קונסרט - קום סורט הצלילים בקונצרט זה שיר אחד."]},{"e":"conclude","h":"להסיק","a":["קום-קלוד - קום קלוד בדרך וּהסיקו מסקנה כמו שצריך.","קונקלוד - קום קלוד את הדלת, הסקנה סגורה כאן."]},{"e":"concrete","h":"בטון","a":["קום-קריט - קום קרט בטון בדרך קו ישר זה.","קונקריט - קום קריט בטון מוצק כל הרחוב."]},{"e":"concurrent","h":"סימולטני","a":["קום-קור - קום קר בזמן סימולטני הכל גם יחד.","קונקורנט - קום קר נט זמן אחד לכל דבר ביחד."]},{"e":"condemn","h":"להשפיל","a":["קום-דנם - קום דנם להשפיל כל אחד שלא צודק כאן.","קונדנם - קום דנ'ם עלבון וגנאי להשפיל זה."]},{"e":"condense","h":"לעבות","a":["קום-דנס - קום דנס עבה יותר כשמעבים את הטל.","קונדנס - קום דנ'ס עבה טיפה משום דבר."]},{"e":"condition","h":"תנאי","a":["קום-דיש - קום די ש' תנאי חובה בכל חוזה זה.","קונדיש - קום די ש תנאי בדיוק קביעה חובה."]},{"e":"conduct","h":"להוביל","a":["קום-דאק - קום דוק את הדרך להוביל קדימה ישר.","קונדאק - קום דוק הובלה ישרה בדרך קדימה."]},{"e":"confer","h":"להתייעץ","a":["קום-פר - קום פר שתי דעות להתייעץ ביחד כאן.","קונפר - קום פר יעץ בחברות שתי דעות טובות."]},{"e":"confess","h":"להודות","a":["קום-פס - קום פס להודות בחטא שלך בכנסייה.","קונפס - קום פס הודאה ברורה וגם בלב."]},{"e":"confide","h":"לגלות סוד","a":["קונפיד - קון פיד, הסוד שלך נפדה אלי בהנחה.","קונ-פיד: בן-בדיה הסוד שלו קונפנציה, גלויה ברבים."]},{"e":"configure","h":"להגדיר הגדרות","a":["קונ-פיגור: הגדרות קונפנציה, את הפיגור תצייני בהגדרות.","קונפיגור - פיגור הגדרות, קונפיג יריץ את השרתים."]},{"e":"confirm","h":"לאשר","a":["קונפרם - קון פרם, פרם את ההודעה אשר בדוא״ל.","קונפירם: כן פירם, אשר וקונפירם את הסכם."]},{"e":"conflict","h":"סכסוך","a":["קונ-פליקט: פליקט בני משפחה, סכסוך מתוך זילות.","קונפליקט - קון פליקט, כשיש סכסוך קונפליקטים."]},{"e":"conform","h":"להתאים","a":["קונ-פורם: פורם צורה, צריך להתאים את הדרישות.","קונפורם - פורם צורה, התאם לפורמט הנדרש."]},{"e":"confound","h":"להבלבל","a":["קונ-פאונד: פאון מצא? לא, בלבל אותו כשמצא.","קונפאונד - פאון בן סבל, בלבול פאון עד סוף."]},{"e":"confront","h":"להעמיד מול","a":["קונ-פרנט: פרנט אבא נתקל בילד, העמיד אותו מול עובדה.","קונפרנט - אבא נתקל, העמד מול והתווכח."]},{"e":"confuse","h":"להבלבל","a":["קונ-יוז: יוז שימוש, כשמשתמשים הרבה - התבלבלו.","קונפיוז - יוז שימוש גרוע, בלבול בשימוש."]},{"e":"congest","h":"להיות עמוס","a":["קונ-גסט: גסט אורח, אורח שמניסים להכניס לעמוס חדר.","קונגסטד - גסט קשה, עמוס בגסטים רבים."]},{"e":"congratulate","h":"לברך","a":["קונ-גרטולייט: גר-אטו-לית, ברכה יפה וטובה מאד.","קונגרטולייט - קונ גר אטו, מברכים בברכה."]},{"e":"congregate","h":"התכנסות","a":["קונ-גרגייט: גר גר קול, קול קהל התכנסות גדולה.","קונגרגייט - גרג רעם, קהל מתכנס בקול."]},{"e":"conjecture","h":"השערה","a":["קונ-ג׳קצ׳ר: ג׳קצ׳ור חיזוי, השערה כמו ניחוש בציד.","קונג׳קצ׳ור - ג׳ק צ׳ור, השערת הצייד על הטרף."]},{"e":"connect","h":"התחברות","a":["קון-נקט: נקט נקודה, נקט קשר בין שתי נקודות.","קונקט - נקט קשר, התחבר דרך הנקטה."]},{"e":"conquer","h":"כיבוש","a":["קונקר - קונ קר, קר שונא כבוש בקרב.","קונקוור - קן קר, קר כבוש בתיקו."]},{"e":"conscious","h":"מודע","a":["קונ-שס: שס שיחה, כשאתה מודע בשיחה.","קונשס - שס מודע, בעת שיחה מודעת."]},{"e":"consecutive","h":"עוקב","a":["קונסקוטיב - קון סקוט, סקוט עקבו בסדר עוקב.","קונסיקיוטיב - סיקו עוקב, דברים אחד אחרי השני."]},{"e":"consensus","h":"הסכמה כללית","a":["קונסנסוס - סנס סיסמה, מחלוקות נעלמו בהסכמה כללית.","קונסנסוס - אנשים נס, הסכמה כלל עלתה."]},{"e":"consent","h":"הסכמה","a":["קון-סנט: סנט ריח טוב, ריח של הסכמה מתוקה.","קונסנט - סנט הולך, הסכמה הלכה לדרך."]},{"e":"consequence","h":"תוצאה","a":["קונסקוונס - קון סק, סקוול תוצאה, תוצאה מבלבלת.","קונסקוונס - סק תוצאה, תוצאת סכסוך."]},{"e":"conserve","h":"שימור","a":["קון-סרב: סרב שימור, שמור ואל תסרב לשמור.","קונסרב - סרב שומר, שמור על הסרב."]},{"e":"consider","h":"שיקול","a":["קון-סידר: סידור חדרים, שקול את הסדור הנכון.","קונסידר - סידור מחשבה, חשוב לפני הסידור."]},{"e":"consist","h":"הרכב","a":["קון-סיסט: סיסט קבוצה, קבוצה כוללת הרכב.","קונסיסט - סיסט הרכב, הרכב מורכב סיסט."]},{"e":"console","h":"נחמה","a":["קונסול - קול של נחמה, ננחם בקול רך.","קונסול - סול בעצב, נחמה בעצב הלב."]},{"e":"consolidate","h":"איחוד","a":["קון-סולידייט: סוליד חזק, איחוד מחוזק וסוליד.","קונסולידייט - סוליד חזק, איחוד חומר חזק."]},{"e":"conspicuous","h":"בולט","a":["קון-ספיקיואוס - ספיק בולט, סלקים בולטים מאד בעין.","קונספיקיואוס - ספיק ניכר, בולט כמו קספיק."]},{"e":"conspire","h":"קנוניה","a":["קונ-ספיר - הם קנוניים בחבורה הקשורה סודית","קונ ספיר כמו קנוניה סודית של קוספירטורים"]},{"e":"constant","h":"קבוע","a":["קונ-סטנט - הוא קבוע כמו אבן בקנטון הקביעה","קונ סטנט - הקביעות קבועה כמו האנגלית שלו"]},{"e":"constituency","h":"בחירה","a":["קונ-סטיטואנסי - בחירות בקונסטיטואציה משנות בחירה","קונ קונסטיטואנסי מביע את בחירת הקונסטיטואציה"]},{"e":"constitute","h":"הרכב","a":["קונ-סטיטיוט - מהרכב של קונסטיטואציה מרכיבה","קונ סטיטיוט היא הרכבה מהצו של הרכב"]},{"e":"constrain","h":"הגבלה","a":["קונ-סטרייין - קשוקוי סטרטיים מגבילים סטראיין הגבלה","קון-סטרייין מהגבלה של קו סטרייניים קשוקים"]},{"e":"construct","h":"בנייה","a":["קונ-סטרקט - בנייה קונסטרוקטיבית בנויה בנקודה","קון סטרקט בניות קונסטרוקטיביות בנויות בביטחון"]},{"e":"consult","h":"ייעוץ","a":["קון-סלט - ייעץ בקול סלט לייעוץ נשמע","קון סולט היעוץ קולי בסלט הקול"]},{"e":"consume","h":"צריכה","a":["קון-סיום - צריכת קונסיום סוגר בעלות קונסום","קון סיום היא צריכה של סיום בקונסום"]},{"e":"contact","h":"יצירת קשר","a":["קון-טקט - יצירת קשר בקטגוריה של קון טק","קון טקט היא קשר טקני בקונטקט"]},{"e":"contain","h":"הכלה","a":["קון-טיין - הכלה בטנק של קונטיינר בהכלה","קון טיין את הדבר בתוך הטיין המוכל"]},{"e":"contemplate","h":"התבוננות","a":["קון-טמפלייט - התבוננות בתבנית של קון טמפ לט","קון טמפלייט היא תבנית של התבוננות עמוקה"]},{"e":"contend","h":"התחרות","a":["קון-טנד - התחרות בטנד של קונטנדים מתחרים","קון טנד בטנדים מתחרים בהתחרויות"]},{"e":"content","h":"תוכן","a":["קון-טנט - התוכן בטנק של קונטנט המלא","קון טנט היא טנק של תוכנים עמוסים"]},{"e":"contest","h":"תחרות","a":["קון-טסט - התחרות בסטטוס של קונטסט במאבק","קון טסט היא מאבק בתחרות סטטסית"]},{"e":"context","h":"הקשר","a":["קון-טקסט - הקשר בטקסט של קונטקסט בהקשר","קון טקסט היא טקסט בקשר הקונטקסטי"]},{"e":"contiguous","h":"צמוד","a":["קון-טיגיוס - צמודים בטיג של קונטיגואוס קרוב","קון טיגיוס טיג קרוב בצמידות קונטיגואוסית"]},{"e":"continent","h":"יבשת","a":["קון-טיננט - יבשת קונטינט בטינה גדולה","קון טיננט היבשת של קונטינט גדול"]},{"e":"contingent","h":"תלוי בתנאים","a":["קון-טינג'נט - תלוי בתנאי קונטינגנט תליון","קון טינג'נט היא תלות של תנאים קונטינגנטיים"]},{"e":"continue","h":"להמשיך","a":["קון-טינו - המשך ניו של קונטינו בהמשך","קון טינו היא המשך של קונטיניות עצמית"]},{"e":"contort","h":"להתפתל","a":["קון-טורט - התפתלות בטורט של קונטורט מתופתל","קון טורט היא טורט מתפתלת בהתפתלות"]},{"e":"contract","h":"חוזה","a":["קון-טרקט - חוזה בטרק של קונטרקט קשור","קון טרקט היא טרקציה של חוזה מחייב"]},{"e":"contradict","h":"לסתור","a":["קון-טרה-דיקט - ניסתור בדיקט של קונטרה סתור","קון טרה דיקט היא דיקציה של ניסתור קונטראדיקטי"]},{"e":"contrary","h":"הפוך","a":["קון-טרר-י - הפוך בטרר של קונטרארי הנגדי","קון טרר-י היא טרור של הפוכות קונטרריות"]},{"e":"contrast","h":"ניגוד","a":["קון-טרסט - ניגוד בטרסט של קונטרסט נגדי","קון טרסט היא טרסט של ניגודים קונטרסטיביים"]},{"e":"contribute","h":"לתרום","a":["קון-טרביוט - תרומה בטרב של קונטריביוט משותף","קון טרביוט היא טרביוציה של תרומה קונטריביוטית"]},{"e":"contrive","h":"לתכנן בתחכום","a":["קונטריב - קונטר טריק: תכנון בתחכום דורש הפוך טריק חכם.","קונטריב - קונה טריב: מי שקונה טריבונל תחכום מתכננים."]},{"e":"control","h":"לשלוט","a":["קונטרול - קונטר רול: שליטה על כל התפקידים בחברה.","קונטרול - קונים טרול: השולט בטרול השחקנים בשיחה."]},{"e":"controversial","h":"שנוי במחלוקת","a":["קונטרוברשל - קונטרה ברשל: דברים שנויים במחלוקת חוצים את הדרך.","קונטרוברשל - קונטרה ברשים: כאשר מחלוקות גורמות להתנגדויות גדולות."]},{"e":"convene","h":"להתכנס","a":["קונווין - קונה וואין: כשקונים וואין הכל מתכנסים להתחיל.","קונווין - קון ווין: קהל קונים ומנצחים מתכנסים בהנאה."]},{"e":"convenient","h":"נוח","a":["קונווניינט - קון וואני אנט: קן שלי כל מה שאני רוצה - זה נוח מאד.","קונווניינט - קונים וואני ענט: לקנות מה שרוצים - כל כך נוח וקל."]},{"e":"conventional","h":"מקובל","a":["קונוונשנל - קון וואן שנל: קן של אחד שנל - זה המקובל המסורתי.","קונוונשנל - קונים וואן שנים: הקונה המקובל של שני דברים."]},{"e":"converge","h":"להתכנס","a":["קונוורג - קון ווור ג': כשקונים הכל על גו - הכל מתכנס למקום אחד.","קונוורג - קן וורג: קן השנים נוורגים להתכנס ביחד."]},{"e":"converse","h":"שיחה","a":["קונברס - קן ברס: קן של שיחה בברווז - תמיד משהו לדבר.","קונברס - קונים ברסה: כשקונים ברסה זה הופך לשיחה נחמדה."]},{"e":"convert","h":"להפוך","a":["קונברט - קן ברט: קן של ברט הופך לדבר אחר - המרה מושלמת.","קונברט - קן ברט: קן שלם שברט הופך לצורה חדשה."]},{"e":"convey","h":"להעביר","a":["קונווי - קן ווי: קן שלי שלח גם לך - העברה של הודעה חשובה.","קונווי - קן ווי: קן הווי שלנו שולח הודעות בקלות."]},{"e":"convict","h":"להרשיע","a":["קונוויקט - קן ווי קט: קן שלי שיודע קט - מרשיע אותו מיד.","קונוויקט - קן ווי קט: קן קט שהרשיעו בעל כרחו."]},{"e":"convince","h":"לשכנע","a":["קונווינס - קן וואינס: קן שלי מוודא - מוכיח ותורה שכנוע.","קונווינס - קן וואינס: קן וינס בשכנוע - משכנע הכל להסכים."]},{"e":"convivial","h":"חברותי","a":["קונוויוויאל - קן וויוויו אל: קן חברים חיים ביחד - חברותי במובן הטוב.","קונוויוויאל - קן ווי וויו: קן שחברותי וחום ומענג."]},{"e":"cooperate","h":"לשתף פעולה","a":["קואופרייט - קו אופר ייט: שניים קו-אופרים יחד - משתפים פעולה בהמון.","קואופרייט - קו אופר אי: קו-אופרטיבית - משתפות פעולה תמיד."]},{"e":"coordinate","h":"לתאם","a":["קואורדינייט - קו אורדי נייט: שניים קו-אורדינים בלילה - מתאמים בדיוק.","קואורדינייט - קו אור דין היי: קו שלי אור - מתאמים בצורה מושלמת."]},{"e":"copious","h":"שופע","a":["קופיוס - קו פיש: דגים שופעים כמו קופיוס - שופע בשפע.","קופיוס - קו פיוס: קו של פיוס שופע - שפע אדיר."]},{"e":"copy","h":"העתק","a":["קופי - קו פיי: קו שלי תמיד פיי - העתק מושלם תמיד.","קופי - קופיה: קופה שלי עם התעתוק - העתק נאמן."]},{"e":"cordial","h":"חם","a":["קורדיאל - קור דיאל: קור של דיאל חם - חום וידידות אמיתית.","קורדיאל - קור דיה: קור שלי דיה - קבלה חמה וחברותית."]},{"e":"core","h":"גרעין","a":["קור - קור אה: קור אה - הגרעין של הדברים המרכזי.","קור - קור ה: קור הכל - הגרעין המרכזי של הכל."]},{"e":"correlate","h":"להתאם","a":["קורילייט - קור אילייט: קור שלי אילי - מתאים ומתקשר בדיוק.","קורילייט - קור ילייט: קור יל מאיר - מתאימים בהדדיות."]},{"e":"correspond","h":"התאים","a":["קורספונד - קור ספונד: קור ספון דן - כתב וגם התאים לי.","קורספונד - קור ספו דן: קור סכום דן - התאימו ויודעות בדיוק."]},{"e":"corroborate","h":"אישר","a":["קורובוריט - קור באור ית: קור שלי בעור אישר - אישור חזק וקל.","קורובוריט - קור ברוריט: קור בברור - אישור וידוק."]},{"e":"corrupt","h":"השחית","a":["קורפט - קור פיט: קור שלי פיט - השחיתות פוגעת בהכל.","קורפט - קור פט: קור פט - השחית את הטוב."]},{"e":"cost","h":"עלות","a":["קוסט - קוס טו: קוס טו משהו עלה לי כסף - עלות כבדה.","קוסט - קוסט - עלות של כל קוסם - עלות גבוהה תמיד."]},{"e":"council","h":"מועצה","a":["קאונסיל - קאו נסיל: קאו נסיל עצה - המועצה נותנת עצה טובה.","קאונסיל - קאו נסיל: קאו שלי נסיל - המועצה שלנו מחליטה."]},{"e":"counsel","h":"ייעץ","a":["קאונסל - קול של עצה, המייעץ שומע קול חכם","הקאונסל כמו 'קול' של האיש החכם שנותן עצות"]},{"e":"counter","h":"התנגד","a":["קאונטר - כמו 'קנטור' הוא נגד הזרם, התנגד כאן","קאונטר בספר הנגדיות - מי שמונה כנגד התנגד"]},{"e":"counteract","h":"ביטל","a":["קאונטר-אקט - קאונטר התנגד, אקט התנגד, ביטל יחד","הקאונטר-אקציה ביטלה את הצעד הקודם בדרמה"]},{"e":"counterpart","h":"עמית","a":["קאונטרפארט - קאונטר כנגדו, פארט כחלק, עמית שחלק עמו חזקות","הקאונטרפארט שלי - העמית שעומדת כנגדי"]},{"e":"countless","h":"אינספור","a":["קאונטלס - קאונט (ספור) לס (אפס), לא יודעים לספור - אינספור","הקאונטלס כוכבים - אי אפשר לספור, אינספור"]},{"e":"couple","h":"זוג","a":["קאפל - זוג קפלים קטנים יוצרים זוג גדול","קאפל - קפל בשניים, זוג מצטרף"]},{"e":"courage","h":"אומץ","a":["קרג - כמו 'קורג' הרגש האמיץ של הקול הגבוה","קוראג' - קור הקור לא פוחד, אומץ רב"]},{"e":"course","h":"קורס","a":["קורס - קוד ישר של הדרך, קורס הלימודים קדימה","קורס - עוברים בקורס, הדרך הנכונה"]},{"e":"courteous","h":"אדיב","a":["קורטיאוס - קורטו (קצר) + אוס (אפילו), קצרה הדברים כשהוא אדיב","קורטן - כמו 'קור' הדברים קצרים עם אדיבות"]},{"e":"cover","h":"כיסה","a":["קוברים - כמו 'קובר' המכסה, כיסה בשכבה","קוברים - קובר יום את הלילה בכיסוי"]},{"e":"covet","h":"חסם","a":["קובט - קבל + טפש, חסם בכוח מהטפש","קובט - קוב טפל - מי שחסם לעצמו"]},{"e":"coward","h":"פחדן","a":["קוורד - קווארד כמו 'קוא' ואחריו 'רד' פחד אדום","קוורד - קו וורוד - פחדן שהפנים אדומות מפחד"]},{"e":"cozy","h":"חם ונוח","a":["קוזי - קוז חם כמו קוא וזיק, חם ונוח כמו בית","קוזי - זיקה לחום, מרגיש חם ונוח"]},{"e":"craft","h":"מלאכה","a":["קראפט - קראה פט (מלאכה קטנה) = מלאכה","קראפט - קרא פת על המלאכה המסורתית"]},{"e":"cram","h":"החזיק","a":["קרם - קרימה מוקצה למלא, החזיק חומר בכוח","קרם - קר מלא - מחזיק דברים בתוך הקרם"]},{"e":"crank","h":"משוגע","a":["קרנק - קרא ונק (משוגע) = משוגע","קרנק - קורנק - קול של אלו שמשוגעים"]},{"e":"crash","h":"התרסק","a":["קראש - קרא ש = התרסק! קרא וש (השמיים נפלו)","קראש - קרא ש - קול התרסקות"]},{"e":"crave","h":"כמה","a":["קרייוו - קריא וו - קרא קול החמדה, כמה","קרייוו - קר + יאוו - צעקת הכמיהה"]},{"e":"crawl","h":"זחל","a":["קרול - קרא + אול, קול שזוחלים בו, זחל","קרול - קר + רוול, הגוף מתגלגל בזחילה"]},{"e":"crazy","h":"טירוף","a":["קרייזי - קרא זי - קול של טירוף בעלי זי","קרייזי - קרא זו - זה קול הטירוף"]},{"e":"create","h":"יצר","a":["קריייט - קרא ייט - קרא לאור חדש, יצר","קריייט - קר + יט - קול המוצר החדש שנוצר"]},{"e":"credible","h":"מאמין","a":["קרדיבל - קרד + בל - מאמינים בקול הנחמד של אמינות","קרדיבל - קרדה בל - מי שמאמין"]},{"e":"credit","h":"הפקיד","a":["קרדיט - קרדה + יט - הפקיד קטנטן את הכסף","קרדיט - קר + דיט - קודם הודה אחר כך הפקיד"]},{"e":"creep","h":"התגנב","a":["קריפ - קרי + פ - צעקת מי שהתגנב בשקט","קריפ - קר + יפו - אור התגנבות בלילה"]},{"e":"crest","h":"פסגה","a":["קרסט - קרא סט - קרא הפסגה בראשית הדרך","קרסט - קר + סט - הקול מן הפסגה"]},{"e":"crisis","h":"משבר","a":["קראיסיס - משבר, כל קראיסיס היא משבר שמחייבת החלטה מהירה.","המילה crises בעברית היא משבר, כשיש קריזה בחברה כל דבר הופך למשבר."]},{"e":"criterion","h":"קריטריון","a":["קריטריון - זה הקריטריון שלי, הקריטריון שבו אבחר.","קריטריון זה קריט-ריון, הקריט של ההחלטה הוא הקריטריון."]},{"e":"critic","h":"מבקר","a":["קריטיק - כל מבקר הוא קריטיק שמוצא דברים לביקורת.","הקריטיק כמו 'קריטי' אומר ביקורת על כל דבר שהוא מבקר."]},{"e":"critical","h":"קריטי","a":["קריטיקל - זה קריטי לחלוטין, מצב קריטי שהוא קריטיקל ומחשוק.","קריטיקל בתרגום ישיר זה קריטי, קריטי ביותר זה קריטיקל."]},{"e":"criticize","h":"לבקר","a":["קריטיקל - כשאתה לבקר, אתה עושה קריטיקל של הדברים.","קריטיקל אומר שאתה לבקר, לבקר זה קריטיקל."]},{"e":"crooked","h":"עקום","a":["קרוקד - הקו העקום שלי קרוקד ונראה עקום.","קרוק זה עקום, דרך קרוקד היא עקומה לא ישרה."]},{"e":"cross","h":"חוצה","a":["קרוס - קרוס את הרחוב, חצה אותו מצד לצד.","כשקרוס קול קורים אתה חוצה את הדרך."]},{"e":"crowd","h":"קהל","a":["קראוד - הקראוד זה קהל, קהל גדול של קראוד.","בקראוד כלומר בקהל גדול, הקהל הוא קראוד."]},{"e":"crucial","h":"קריטי","a":["קרוושל - קרו-של זה קריטי לחלוטין, השל הוא הקריטי שלך.","קרוושל זה קריטי, קריטי ביותר זה קרוושל."]},{"e":"crude","h":"גס","a":["קרוד - גס וגס, קרוד זה גס ובלי עדינות.","קרוד הוא גס, חומר גס זה קרוד."]},{"e":"cruel","h":"אכזר","a":["קרואל - קרו אל, אל הרוע אתה קרואל וזו אכזריות.","קרואל כמו קרוע, קרוע בלב זה אכזרי."]},{"e":"crumb","h":"פירור","a":["קרמב - קרום של לחם בא לפירור קטן.","קרמב זה פירור, כשלחם יוצא קרמב הוא נשבר."]},{"e":"crumble","h":"להתפרך","a":["קרמבל - קרום בל, כשלחם קרום הוא מתפרך.","קרמבל פירור, פירורים מתפרכים ונופלים."]},{"e":"crush","h":"למעוך","a":["קראש - אתה קורא שש, אתה לוחץ ומעוך בכח.","קראש זה למעוך, מעוך בכח קשה זה קראש."]},{"e":"cryptic","h":"מסתורי","a":["קריפטיק - קריפ של סוד, קריפטיק זה מסתורי ומכוסה.","קריפטיק זה סוד, מסתורי זה קריפטיק בחושך."]},{"e":"crystal","h":"קריסטל","a":["קריסטל - קריסטל זה קריסטל, קריסטל זה שקוף וברור.","קריסטל הוא קריסטל, קריסטל בריא זה צלול."]},{"e":"cue","h":"רמז","a":["קיו - קיו זה קו, קו קטן שהוא רמז לחלק הבא.","קיו כמו הקו של הרמז, קיו זה רמז."]},{"e":"culminate","h":"להגיע לשיא","a":["קולמינייט - קול מינייט, בקול גבוה אתה מגיע לשיא.","קול מינייט זה להגיע לשיא, השיא של הקול."]},{"e":"culprit","h":"אשם","a":["קל פריט - קל מלחמה אבל הפריט הוא אשם בהכל.","קל-פריט זה אשם, המאשים את הפריט אשם."]},{"e":"cultivate","h":"לטפח","a":["קל טיבייט - קל תיבה של אדמה, תיבה שאתה טופח אותה.","קל-טיב זה לטפח, טיב ותוכן של טוב לטפח."]},{"e":"cultural","h":"תרבותי","a":["קל-טוראל - קל טור של תרבות, טור תרבותי.","קלטור זה תרבות, טור תרבותי קל-טוראל."]},{"e":"cumbersome","h":"מסורבל","a":["קמברסום - קום בר סום, כשאתה קום בכובד זה מסורבל.","קמברסום זה כבד, כבד ומסורבל זה קמברסום."]},{"e":"cumulative","h":"מצטבר","a":["קיומולייטיב - קיום לטיב, קיום שמצטבר עם הזמן.","קיום לייטיב זה מצטבר, קיום מצטבר זה קיומולייטיב."]},{"e":"cunning","h":"ערום","a":["קנינג - קנה דבר, ערום קנה את הדבר בחוכמה.","קנינג זה ערום, ערום וחכם זה קנינג."]},{"e":"curb","h":"לבלום","a":["קרב - קרב לבלום, לבלום את הדחף האנושי.","קרב זה בלום, בלום את הדחפים זה קרב."]},{"e":"cure","h":"תרופה","a":["קיור זה קול כמו 'קיים אור' - התרופה מחזירה אורך ימים.","הקיור מקרם את החולה כמו 'קי אור' שמביא רפואה."]},{"e":"curiosity","h":"סקרנות","a":["קיוריוסיטי - קיור יו סיטי, סקרן שרוצה לדעת הכל בעיר.","קיוריוסיטי - קיו-רי-א-סיטי, כשאתה סקרן אתה שואל רבות שאלות."]},{"e":"current","h":"זרם","a":["קרנט כמו 'קר נט' - הרياح הקרות יוצרות זרם אוויר.","קרנט קול כמו 'קר' בעברית, הזרם בים קר מאוד."]},{"e":"curriculum","h":"תכנית לימודים","a":["קריקולום - קרי קולום - תכנית הלימודים קוראת לכם בקולות שונים.","קריקולום - קרי קול - תכנית הלימודים מדברת בקול למורים ולתלמידים."]},{"e":"curse","h":"קללה","a":["קרס קול כמו קרע - הקללה קוראת לקרע בנשמה.","קרס - קר אסור, הקללה היא דבר קר שאסור להטיל."]},{"e":"cursory","h":"משטחי","a":["קרסורי - קר סור, בחינה משטחית היא קרה וסופרת בדיוק פחות.","קרסורי קול כמו 'קור' - תצפית משטחית מקורה ולא עמוקה."]},{"e":"curtail","h":"להפחית","a":["קרטייל - קר טיל, להפחית את הקילו האפל בתכנית.","קרטייל - קרט יל, קיצור וטל של הביטחון להפחית בו."]},{"e":"curve","h":"עקומה","a":["קרב זה קול של 'קרבולה' - העקומה תמיד קרבה לעצמה.","קרב - קרוב, העקומה תמיד חוזרת לקרבה שלה."]},{"e":"custody","h":"הסכם","a":["קסטודי - קס טו די, הסכם להגנה בשפל ובדי.","קסטודי - קס טודי, הסכם להגנה על הילד בימים אלה."]},{"e":"custom","h":"מנהג","a":["קסטום - קס טום, המנהג היהודי קס טום עבר דורות.","קסטום - קס טוב - מנהג טוב שנשמר בקדומים."]},{"e":"customary","h":"המתחייב","a":["קסטומרי - קס טום רי, המתחייב מנהג קדום ששורד.","קסטומרי - קס טום - ממנהג ישן החובה המתחייבת בלי בדיקה."]},{"e":"cut","h":"לחתוך","a":["קט - קציץ, כשאתה חותך אתה צריך 'קט' אחד חזק.","קט - קציץ תרנגול, כדי לחתוך צריך ציוד חד."]},{"e":"cycle","h":"מחזור","a":["סייקל - צייקל כמו 'צי' בעברית, המחזור של הים והדגים.","סייקל - צייקל, המחזור חוזר שוב וכאן צי של מחזוריות."]},{"e":"cynical","h":"ספקן","a":["סיניקל - ס יניק ל, הספקן יניק את התקווה מהחיים.","סיניקל - סין יקל, הספקן סיני הדעות וקל להתאכזל."]},{"e":"daily","h":"יומי","a":["דיילי - די יום לי, כל יום וקדושה יום אחד לי בריא.","דיילי - דיום לי, הרגל יומי שלי כל בוקר נדלק."]},{"e":"damage","h":"נזק","a":["דמג - דם עוג, הנזק שגרם דם ועוג רחב.","דמג - דם עוג, כשנזק גדול זה גם דם וגם עוג בחוקים."]},{"e":"damp","h":"רטוב","a":["דמפ - דם פ, הרטיבות בדם וברטיבות סביב.","דמפ - דם פח, כשרטוב בחוץ הדם בפחות חיזוק."]},{"e":"danger","h":"סכנה","a":["דיינג - דיין ג, הסכנה היא כמו דיין שמקבל גרום.","דיינג - דיין ג, זה בסכנה כמו דיין בגרומיות."]},{"e":"dare","h":"להעז","a":["דייר - דיי אר, להעז זה לדבר בדיי אופי טוב.","דייר - די אר - להעז צריך די אומץ רב בלב."]},{"e":"dark","h":"חשוך","a":["דארק - דר קק, החשוך הוא דר קודם לתורים.","דארק - דר ק - החשוך הוא כמו דרך בלתי ברורה."]},{"e":"dash","h":"מקף","a":["דאש - דש, המקף הוא כמו דש בהתנגשות קטנה.","דאש - דש בסימן, מקף זה כמו דש במילה שמתפרדת."]},{"e":"data","h":"מידע","a":["דייטה - די טה, המידע הוא די טוב ושימושי הרבה.","דייטה - דייט הא - המידע דייטס את החוקרים בחוקי."]},{"e":"daunt","h":"להרתיע","a":["דונט - דו אנט, להרתיע הוא כמו דו שאני אנט עוצר.","דונט - דו אנט - להרתיע זה לומר לא עוד פעם."]},{"e":"dawn","h":"שחר","a":["דן - דן אור, השחר הוא כאן דן שמביא אורים.","דן - דן בשחר בוקר דן בעדות עם האור הראשון."]},{"e":"dazzle","h":"להבהיק","a":["דאזל - דאז ל, להבהיק זה קול דאז של אור.","דאזל - דאז אל - להבהיק הוא כמו ברק קול דאז."]},{"e":"dead","h":"מת","a":["דד - מת, מוות שם. Dead זה צליל של מישהו מת שנופל - דד!","דד - הצליל החוזר קטע כמו לב שמפסיק לעבוד, מת."]},{"e":"deadline","h":"מועד סופי","a":["דד-ליין - הקו האדום הסופי שלא חוצים, מועד סופי.","דד ליין - המתים מגיעים לקו הסוף, זה המועד הסופי."]},{"e":"deadly","h":"קטלני","a":["דדלי - קול מת וקוטלני, משהו שמוביל למוות.","דדלי חוזר - היציאה המקומית החזקה וקטלנית, קיטול."]},{"e":"deaf","h":"חרש","a":["דף - צליל של פה שלא שומע, חרש כמו דף שלא מדבר.","דף - הצליל הקל של דף, אבל החרש לא שומע אותו כלל."]},{"e":"deal","h":"עסקה","a":["דיל - צליל עסקה, סיפור של מטבח שמתחסן דיל בעסקה.","דיל זה די אל - די הרבה בעסקה, די סיפור של עסקה טובה."]},{"e":"dear","h":"יקר","a":["דיר - קול של יקר וחיבה, משהו שאתה קורא לו דיר יקר.","דיר - כמו דיור יקר מאוד, זה יקר לבב שלך."]},{"e":"dearth","h":"מחסור","a":["דארת - צליל של מחסור, דחוי וחסר. Dearth זה מילה של דחקה ודחיקה.","דארת - דחוק ודרוש מחסור, כשאין מספיק זה dearth."]},{"e":"debate","h":"ויכוח","a":["דבייט - זה ניגוד של 'בייט' (קבלה), דבר שמתנגד וויכוח.","דבייט - די בייט, חיכוך של דעות, ויכוח מלא."]},{"e":"debris","h":"שברים","a":["דברי - שברים של דברים שנופלים, debris זה קולות דברים נשברים.","דברי זכר - השברים הנישארים זוכרים את הנפילה."]},{"e":"debt","h":"חוב","a":["דבט - צליל כבד של משהו שתלוי עליך, חוב כבד.","דבט - די בעט (מכה), החוב מכה וכואב, משהו שתלוי עליך."]},{"e":"decade","h":"עשור","a":["דקיד - עשור זה עשר שנים, דקיד קול של עברת זמן.","דקיד - קול עמום של עשור שעובר, זמן חולף בשקט."]},{"e":"decay","h":"התפרקות","a":["דיקיי - זה קול של התפרקות, די קיי כמו קול שמתפרק ונופל.","דיקיי - קול מומלל של התפרקות טבעית, דיקיי זה סיוע."]},{"e":"deceive","h":"להטעות","a":["דיסיב - סיב שמטעה, צליל נחמד שמסתיר, להטעות בעדינות.","דיסיב - די סיב (סיבה כוזבת), מטעות דרך סיבות כוזבות."]},{"e":"decent","h":"הגון","a":["דיסנט - צליל נעים של הגון, די סנט (ריח טוב), משהו הגון.","דיסנט - צליל של מישהו שעולה בהצדקה, משהו הגון ויפה."]},{"e":"decide","h":"להחליט","a":["דיסיד - זה קול של החלטה שנחתכת, די ציד (ציד החלטה).","דיסיד - צליל של גזירה, סידור סופי, להחליט בחוק."]},{"e":"decimal","h":"עשרוני","a":["דיסימל - זה עשרוני משום שהצליל הוא עדין וחלק כמו נקודה עשרונית.","דיסימל - די סימל, סימול עשרוני, מספר דק ודקיק."]},{"e":"decipher","h":"לפענח","a":["דיסיפר - זה צליל של פענוח, די סיפור שמתפענח לאט לאט.","דיסיפר - די סיפור (קוד הסיפור), לפענח את הקוד בעדינות."]},{"e":"decision","h":"החלטה","a":["דיסיזן - סיזון של החלטה, די סיזון צפוי, החלטה גורלית.","דיסיזן - די סיזון חדש, החלטה שמתחילה עידן חדש בחיים."]},{"e":"decisive","h":"חיוני","a":["דיסיסיב - זה צליל של משהו שחיוני מאוד, די סיס אב (מערכת אב).","דיסיסיב - משהו שחותך את הזמן, קריטי וחיוני לחלוטין."]},{"e":"declare","h":"להצהיר","a":["דיקליר - כמו קלירות של הצהרה, די קליר (ברור), להצהיר בבהירות.","דיקליר - קול של הצעה ברורה, הצהרה שלא משאירה ספק."]},{"e":"decline","h":"להידרדר","a":["דיקליין - קול של נפילה וירידה, די קליין (קטן), להידרדר.","דיקליין - קו שיורד ונחלש, קלין פירושו הסתיים, הידרדרות."]},{"e":"decode","h":"לפענח","a":["דיקוד - קוד שמפוענח, די קוד פנימי, לפענח מסר מוצפן.","דיקוד - די קוד אני קורא, אני מפענח את הקוד הנסתר."]},{"e":"decompose","h":"להתפרק","a":["דיקומפוז - קול של התפרקות, די קומפוז (יצור), להתפרק בהדרגה.","דיקומפוז - קומפו זה קומה שנופלת, התפרקות טבעית."]},{"e":"decorate","h":"לעטר","a":["דיקוריט - קול של עיטור נוסף, די קוריא (קישוט), לעטר את החלל.","דיקוריט - קור אית, קור אם מלא קישוטים, לעטר בחן."]},{"e":"decrease","h":"להפחית","a":["דיקריס - קול של הפחתה חדה, די קריסה (התרסקות), להפחית בחדות.","דיקריס - כמו הקריסה הקטנה, הפחתה שמתרחשת ببטיחות."]},{"e":"decree","h":"גזרה","a":["דִיקְרִי - המלך דִיקְרֵט גזרה חדשה על כל העם.","דִיקְרִי קול - כשהמלך גוזר גזרה, כולם חייבים לשמוע."]},{"e":"dedicate","h":"להקדיש","a":["דֶדִיקֵיט את עצמך - להקדיש את כל הנפש לעבודה הקדושה.","דֶדִיקֵיט חיים - אדם הקדיש את חייו למטרה אחת."]},{"e":"deduce","h":"להסיק","a":["דִידוּס מהראיות - להסיק מסקנות מעדויות הקיימות.","דִידוּס הלוגיקה - מהנתונים אפשר להסיק אמת."]},{"e":"deduct","h":"לנכות","a":["דִידַקט מהשכר - לנכות כסף מהמשכורת החודשית.","דִידַקט עשרה אחוז - בנקה נוכה עמלה מהחשבון."]},{"e":"deed","h":"מעשה","a":["דִיד - המעשה הטוב שלך הוא דִיד של צדקה.","דִיד גדול - כל מעשה בעולם משאיר חותם."]},{"e":"deep","h":"עמוק","a":["דִיפ בתוך - העמוק ביותר הוא הים, דִיפ וחשוך.","דִיפ הרגש - הרגשות עמוקים מאוד בלב."]},{"e":"deface","h":"להשחית","a":["דִיפֵייס את הקיר - להשחית את הפנים של הקיר בצבע.","דִיפֵייס ההיסטוריה - הזמן משחית כל דברים ישנים."]},{"e":"defame","h":"להשמיץ","a":["דִיפֵים - השמץ על השם של המישפחה.","דִיפֵים עלי - כולם משמיצים אותי בכל מקום."]},{"e":"default","h":"כשל","a":["דִיפוֹלט - כשלון בתשלום חוב כרוך בכשל.","דִיפוֹלט בנק - החברה נכשלה ובנקל הפסיקה הלוואות."]},{"e":"defeat","h":"להביס","a":["דִיפִית אותו - להביס את האויב בקרב גדול.","דִיפִית בתחרות - היא הביסה את כל המתחרות בקלות."]},{"e":"defect","h":"פגם","a":["דִיפֶקט בתוצר - פגם בתפקוד של המוצר החדש.","דִיפֶקט קל - הפגם הקטן הפך את הדבר לבעיה."]},{"e":"defend","h":"להגן","a":["דִיפֶנד עצמך - להגן על עצמך מפני התקפה כלשהי.","דִיפֶנד אחיך - חייב אתה להגן על קרובך."]},{"e":"defer","h":"לדחות","a":["דִיפֶר את ההחלטה - לדחות את ההחלטה לזמן אחר.","דִיפֶר הדיון - העם דחה את הישיבה לשבוע הבא."]},{"e":"defiance","h":"התנגדות","a":["דִיפַיאנס מלא - התנגדות מלאה כלפי הסמכות.","דִיפַיאנס לחוקים - התנגדות גוברת לכל חוק חדש."]},{"e":"deficient","h":"חסר","a":["דִיפִישנט בנקודה - החסר של תרופה גורם למחלה.","דִיפִישנט במזון - תזונה חסרה בחלבונים פוגעת בבריאות."]},{"e":"define","h":"להגדיר","a":["דִיפַיין את המושג - להגדיר בדיוק מה פירוש המילה.","דִיפַיין בשפה - המילון מגדיר כל מילה בעברית."]},{"e":"definite","h":"מוגדר","a":["דִיפִינִיט תשובה - תשובה מוגדרת וברורה לשאלה.","דִיפִינִיט גבול - הגבול מוגדר בדיוק על המפה."]},{"e":"deform","h":"לעוות","a":["דִיפוֹרם את הפנים - לעוות את החזות היפה של הפרצוף.","דִיפוֹרם בכוח - הכוח עווה את הצורה המקורית."]},{"e":"defraud","h":"להונות","a":["דִיפְרוֹד אדם - להונות אדם בעסקה כלשהי.","דִיפְרוֹד כסף - הוא הונה ולקח כל הכסף שלי."]},{"e":"deft","h":"זריז","a":["דֶפְט בידיים - זריז וקל בכל תנועה של הידיים.","דֶפְט קאט - החתול הזריז תפס את העכבר בנקל."]},{"e":"defy","h":"להתרוממות על","a":["דִיפַיי את הכללים - להתרוממות על כללים בפעם אחת.","דִיפַיי את המלך - העם התרומם כנגד הנושל."]},{"e":"degenerate","h":"להיות בנמוכה רמה","a":["דִידֶג׳נֶרֵיט למצב רע - להיות בנמוכה רמה של השפלה.","דִידֶג׳נֶרֵיט החברה - החברה הייתה בנמוכה רמה של כושל."]},{"e":"degrade","h":"להשפיל","a":["דִידְרֵיד את כבודו - להשפיל את הכבוד של אדם בעיניים.","דִידְרֵיד דרגה - הצבא הורד את הדרגה שלו בקנס."]},{"e":"degree","h":"תואר","a":["דִידְרִי של תואר - קבלת תואר אקדמי מהאוניברסיטה.","דִידְרִי גבוה - תואר מכללה נחשב כתואר גבוה."]},{"e":"dehydrate","h":"להסיר לחות","a":["דִיהַידְרֵיט המזון - להסיר לחות מהמזון בחום.","דִיהַידְרֵיט פרות - הפרות המיובשות הסירו כל לחות."]},{"e":"deity","h":"אלוהות","a":["דיטי - אלוהות, הדיוטי שלנו לכבד את האלוהות.","די טי - די טוב שאנחנו מאמינים באלוהות."]},{"e":"delay","h":"לעכב","a":["דיליי - לעכב, כשאתה דיליי-ש זמן, אתה עוכב.","די ליי - זה לא בסדר לעכב וקבע שקר."]},{"e":"delegate","h":"למינוי","a":["דליגט - למינוי, דל גט - מנהל שלנו קיבל דליגיישן.","די ליגיט - זה לגיטימי למינוי מישהו לתפקיד."]},{"e":"delete","h":"למחוק","a":["די-ליט - למחוק, זה די קל ליט את הטקסט.","דיליט - מחקת, כשאני דוחף דיליט, הכל נמחק."]},{"e":"deliberate","h":"לשקול","a":["דיליברט - לשקול, דיליברט עם עצמך לפני שתקבל החלטה.","די ליברט - זה דורש חופש (ליברט) בשקול."]},{"e":"delicate","h":"עדין","a":["דליקט - עדין, זה דליקט מאד, כמו סיבוב עדין.","דיליקיט - יש כאן דלקת? לא, זה עדין מאד!"]},{"e":"delicious","h":"טעים","a":["דיליישס - טעים, די ליישיס - די מאד לא שכחתי טעם כמו זה.","דיליישס - דיי, זה לשוס (טעים) מעולה!"]},{"e":"delight","h":"ליהנות","a":["דילייט - ליהנות, די לייט - זה די קל להנות מזה!","די לייט - אני דאליט (שמח) בזה."]},{"e":"delineate","h":"לתאר בקווים","a":["דילנייט - לתאר בקווים, די לינייט - זה די ברור עם קוים.","דיל אנייט - למחוק קוים? לא, לתאר אותם!"]},{"e":"delinquent","h":"עבריין","a":["דילינקוונט - עבריין, די לינק מהרע - הוא קשור לעברייין.","דיל אינקוונט - עבריין שלא משלם חוב."]},{"e":"deliver","h":"למסור","a":["דיליברר - למסור, די ליברר - זה די משומר במסירה.","די-לי-ברר - מי יספר? האיש שמוסר ההודעה!"]},{"e":"delude","h":"להטעות","a":["דילוד - להטעות, די לוד - טעון שקר להטעות אותנו.","די לוד - הוא טעמון (לוד) בהטעות אותנו."]},{"e":"deluge","h":"הצפה","a":["דילודג' - הצפה, די לודג' - הוא לא הצליח להסגר בלודג'.","דיל אודג' - מים הצפו ולא ניתן להסגר."]},{"e":"delve","h":"לחפור","a":["דלווה - לחפור, דל וה - דל בעד פנימה לחפור!","דיל וה - דל ממש לחפור כאן."]},{"e":"demand","h":"לדרוש","a":["דימאנד - לדרוש, די מאנד - דרוש (מאנד) עם כוח!","די מעונד - זה לא טוב לדרוש כל הזמן."]},{"e":"demeanor","h":"התנהגות","a":["דימינור - התנהגות, די מינור - כל כך קטן (מינור) התנהגותו.","די מינור - ההתנהגות של קטן (מינור) וצנוע."]},{"e":"demise","h":"מוות","a":["דימייז - מוות, די מייז - די קצר הדרך למוות.","די מייז - זה הסיום (מייז) של החיים."]},{"e":"demolish","h":"להרוס","a":["דימוליש - להרוס, די מוליש - זה די קל להרוס (מוליש).","די מול - אתה רואה (מול) את ההריסה?"]},{"e":"demonstrate","h":"להדגים","a":["דימונסטרייט - להדגים, די מונו - אני מראה (מונו) כך להדגים.","די מנשה - מנשה היהודי הדגים (הראה) כוח."]},{"e":"demote","h":"להוריד בדרגה","a":["דימוט - להוריד בדרגה, די מוט - היה די כעס שהורדו בדרגה.","די מוט - מוטר מהמקום עליון!"]},{"e":"demure","h":"צנוע","a":["דימיור - צנוע, די מיור - די אחרי-קול (מיור) בתמונות צנוע.","די מיור - הוא צנוע (מיור) מאד."]},{"e":"denial","h":"הכחשה","a":["דיניאל - הכחשה, די ניאל - זה די לא נחמד להכחיש (ניאל).","די נו אל - זה לא קבלת אמת אלא הכחשה."]},{"e":"denounce","h":"להאשים","a":["דינאונס - להאשים, די נאונס - זה די רע להאשים (נאונס).","די-נו אנס - הוא הואשם לפני הכל."]},{"e":"dense","h":"צפוף","a":["דנס - צפוף, דנס - רכות צפוף (דנס) מאד!","דיינס - די הצפיפות כאן (דנס) גבוהה מאד."]},{"e":"dent","h":"שקע","a":["דנט - שקע, דנט - זה שקע קטן בדנט!","דנט - יש שקע קטן בשפוגית."]},{"e":"deny","h":"להכחיש","a":["דיני בקורט: הוא הכחיש את ההאשמה בתוקף.","די ניי! הרופא הכחיש את האבחנה הלא נכונה."]},{"e":"depart","h":"לעזוב","a":["דה פרט היום: הנוסעים עזבו את הערים.","די פארט ובחרנו לעזוב את הבית מיד."]},{"e":"depend","h":"להיות תלוי","a":["די פנד על חברים: אנו תלויים זה בזה תמיד.","תלוי בהם, די פנד עליהם בכל עת."]},{"e":"depict","h":"לתאר","a":["די פיקט את התמונה: הוא תיאר את הנוף בדייקנות.","ציור פיקט את המנזר בפרטים יפים."]},{"e":"deplete","h":"להתחסן","a":["די פליט את הסחורה: החנות התחסנה לחלוטין.","לא נשאר כלום, ה״די פליט״ הכל."]},{"e":"deplore","h":"להרגיש צער","a":["די פלור צעקה: היא הרגישה צער עמוק על ההפסד.","בכיה וצער, די פלור בקול גבוה."]},{"e":"deploy","h":"לפרוס","a":["די פלוי החיילים: הצבא פרס את הכוחות בשדה הקרב.","הפרוסה של די פלוי בתמרון מושלם."]},{"e":"deport","h":"לגרש","a":["די פורט אחרון: הממשלה גרשה את המשפחה החוצה.","גירוש קשה, די פורט הם מיד."]},{"e":"deposit","h":"הפקדון","a":["די פוזיט בבנק: הוא הפקיד את כספו בחסיון.","הפקדון בדי פוזיט בטוח וסגור."]},{"e":"deprave","h":"להשחית","a":["די פרייב את הנשמה: החטא השחית את הנוער.","השחתה כמו די פרייב שהרסה הכל."]},{"e":"deprecate","h":"להתנגד","a":["די פריקייט בתור: הוא התנגד בחוזקה לתוכנית.","התנגדות די פריקייט מפורשת וברורה."]},{"e":"depreciate","h":"להפחית בערך","a":["די פרישייט הערך: המשבר הפחית את מחיר הדירה.","הפחתה קשה, די פרישייט שרעה."]},{"e":"depress","h":"להעיק","a":["די פרס על הלב: הדאגה העיקה עליו מאוד.","לחץ כבד כמו די פרס בנשימה עמוקה."]},{"e":"deprive","h":"לשלול","a":["די פריי מנו: השם שלול ממנו לחלוטין.","שלול זכויות כמו די פריי מכל דבר."]},{"e":"depth","h":"עומק","a":["דפת עמוקה: הבאר בעומק של מאה מטר.","עומק המדבר כמו דפת ללא סוף."]},{"e":"deputy","h":"סגן","a":["דפיוטי קטן: הסגן שירת במרץ בכל מקום.","סגן או דפיוטי, הוא חיוביי למעלה."]},{"e":"derail","h":"לשחור מנקביל","a":["די ריל בעקיפין: הרכבת שחרה מהמסלול לחלוטין.","שחרור מנקביל כמו די ריל אל הצד."]},{"e":"derive","h":"להפיק","a":["די ריייב מן התרבות: הוא הפיק התנהגות מהעולם.","הפקה גדולה כמו די ריייב מצדקה."]},{"e":"descend","h":"לרדת","a":["די סנד למטה: המדרגות רדות לחדר התחתון.","ירידה מוגבלת כמו די סנד בקצב אטי."]},{"e":"describe","h":"לתאר","a":["די סקרייב בספר: הוא תיאר את הסיפור בכל פרט.","תאור פרטני כמו די סקרייב בדיוק."]},{"e":"desert","h":"מדבר","a":["דזרט חם: המדבר היה יבש ושומם לחלוטין.","מדבר אדום כמו דזרט בחום קיץ."]},{"e":"deserve","h":"ראוי","a":["די זרוו לקבל: הוא ראוי לתגמול הטוב ביותר.","ראוי זה די זרוו הוגן ותמריץ."]},{"e":"design","h":"עיצוב","a":["די זיין לאמנות: האמן עיצב את הבית בסגנון מודרני.","עיצוב יפה כמו די זיין אומנותי."]},{"e":"designate","h":"להגדיר","a":["די זיגנייט את החוק: המנהל הגדיר את הכללים בדיוק.","הגדרה ברורה כמו די זיגנייט פורמאלית."]},{"e":"desire","h":"רצון","a":["די זייר הוא חזק: הרצון שלו לזכות היה עז.","רצון עז כמו די זייר להשיג הכל."]},{"e":"desist","h":"להפסיק","a":["דה-סיסט: הסיסט שלי לא סיסט ואני הפסקתי לנסות.","דה-סיסט בצליל של סיסט - להפסיק את הסיסט של המנוע."]},{"e":"desolate","h":"שומם","a":["דה-סולט: הבית הוא דה-סולט, שומם וריק לגמרי.","דה-סולט - המקום הישן הוא סולט, שומם ונטוש."]},{"e":"despair","h":"ייאוש","a":["דה-ספייר: כשדה-ספיר נעלם, יש ייאוש וכמיהה.","דה-ספייר - לא יש אור (ספייר), רק ייאוש עמוק."]},{"e":"desperate","h":"נואש","a":["דה-ספרט: הוא נואש כל כך שהפך לדה-ספרט, נכנע.","דה-ספרט, חיל אחרון, נואש וללא תקווה."]},{"e":"despise","h":"בז","a":["דה-ספייז: את זה ספייז (בוז), אני בוז בדה-ספייז.","דה-ספייז, הוא בוז בזלזול, משפיל את הכל."]},{"e":"despite","h":"למרות","a":["דה-ספייט: למרות הדה-ספייט שלו, הוא זכה.","דה-ספייט, למרות הכל ודה-סף של הכעס."]},{"e":"despoil","h":"לבזוז","a":["דה-ספויל: הם בזזו לבזוז את הממלכה דה-ספויל.","דה-ספויל, אדם שבוזז וזילזל, מבזז רכוש."]},{"e":"despondent","h":"כחוש","a":["דה-ספונדנט: הוא כחוש ודה-ספונדנט, שברור נוח.","דה-ספונדנט, כחוש כחושת אפילה, דיכאון עמוק."]},{"e":"destine","h":"לגזור","a":["דה-סטיין: הגורל דה-סטיין לו, כל דבר גזור לו.","דה-סטיין, כל דבר גזור לעתיד שלו מראש."]},{"e":"destitute","h":"עני","a":["דה-סטיטיוט: הוא עני ודה-סטיטיוט, בלי כלום.","דה-סטיטיוט, ללא טיטול או רכוש, עני מוחלט."]},{"e":"destroy","h":"להשמיד","a":["דה-סטרוי: הרעקטור חזק כל כך שדה-סטרוי הכל.","דה-סטרוי, ההרס שלו טרוי, הרס הכל."]},{"e":"detach","h":"לנתק","a":["דה-טאץ': הוא דה-טאץ' לי בכוח, נתק אותי.","דה-טאץ', לא טאץ' יותר, להנתק לגמרי."]},{"e":"detail","h":"פרט","a":["די-טייל: די-טייל קטן וגדול, כל פרט חשוב.","די-טייל, כל טייל קטן של התיל הוא פרט."]},{"e":"detain","h":"לעכב","a":["דה-טיין: הוא דה-טיין אותי, עיכב את ההליך.","דה-טיין, הקטין דה-טיין אותי בעיכוב בלתי צפוי."]},{"e":"detect","h":"לגלות","a":["דה-טקט: אני דה-טקט את הבעיה, גיליתי אותה.","דה-טקט, הטקט של האדם היה קל לגלויה."]},{"e":"deter","h":"להרתיע","a":["דה-טר: הוא דה-טר מאומץ נועז, הרתיע אותו.","דה-טר, טר האויב רועד מהבחילה והרתעה."]},{"e":"deteriorate","h":"להתדרדר","a":["דה-טריורט: הרוח דה-טריורט, התדרדרות הולכת וגדלה.","דה-טריורט, המעמד טריורט לגרוע בהדרגה חמורה."]},{"e":"determine","h":"לקבוע","a":["דה-טרמיין: אני דה-טרמיין, קבעתי וקיבלت החלטה.","דה-טרמיין, טרמיין את העתיד, קבע אותו."]},{"e":"detest","h":"לשנוא","a":["דה-טסט: אני דה-טסט את הטעם שלו, שנאתי.","דה-טסט, טעם זה תסט נורא, שנאתי אותו."]},{"e":"detour","h":"סיבוב עוקף","a":["דה-טור: הדרך דה-טור, עקיפה סבובית מיותרת.","דה-טור, טור ארוך ועוקף בסיבוב מלא."]},{"e":"detract","h":"להפחית","a":["דה-טרקט: זה דה-טרקט מהערך, הפחית הכל.","דה-טרקט, הטרקט שלו מוריד את הכל."]},{"e":"detriment","h":"נזק","a":["דה-טרימנט: זה נזק דה-טרימנט לתוכנית שלי.","דה-טרימנט, הטרימנט שלו גורם נזק ממשי."]},{"e":"devaluate","h":"להוריד ערך","a":["דה-וואליוט: הכסף דה-וואליוט, הורדנו את הערך.","דה-וואליוט, וואליוט היום פחות מתמול בערך."]},{"e":"devastate","h":"להחריב","a":["דה-וואסטט: הערים דה-וואסטט, הוחרבו לחלוטין.","דה-וואסטט, הבסט דה-וואסטט, חורבן מוחלט."]},{"e":"develop","h":"להתפתח","a":["דה-וולופ: התוכנית דה-וולופ, התפתחה ותהתקדמה.","דה-וולופ, הלופ שלו קדמה בהתפתחות מדהימה."]},{"e":"deviate","h":"לסטות","a":["דביאיט אתה לסטות מהדרך הישרה","ה-דיוויאט סטה משמאל, לסטה מהדרך"]},{"e":"device","h":"התקן","a":["דיוויס אות התקן טכנולוגי חדש","התקן הדיוויס מותקן בקיר"]},{"e":"devise","h":"להמציא","a":["דיוויז - דמיון, הממציא תכנן הכל","היא דבזת (דביז) ויצרה כל דבר חדש"]},{"e":"devoid","h":"חסר","a":["דבויד - חסר ממש, כמו חסרון בזול","הוא דבויד מחמלה, חסר לגמרי"]},{"e":"devote","h":"להקדיש","a":["דבוט - התחייבות דתית, הקדיש עצמו","הוא דבוט לתורה, הקדיש חייו"]},{"e":"devour","h":"לטרוף","a":["דיוור - טורף טרף בעוצמה גדולה","הגדול דבור וטרף את ההצלה"]},{"e":"devout","h":"דתי","a":["דיוואוט - צדיק דתי, דבוק בדת","הזקן הדיוואוט היה דתי ונאמן"]},{"e":"dexterous","h":"זריז","a":["דקסטרס - זריז בידיו, דקסטר שמאל-ימין זריז","הקוף הדקסטרוס זריז מאוד בעצים"]},{"e":"diabolic","h":"שטני","a":["דיאבוליק - דבול, דבר שטני וחשוך","האיש הדיאבוליק היה שטני ורשע"]},{"e":"diagnose","h":"לאבחן","a":["דיאגנוז - אבחון מדויק, דיאגנוסה לאבחן","הרופא דיאגנוז את המחלה בדיוק"]},{"e":"diagonal","h":"אלכסוני","a":["דיאגונל - אלכס חוצה בזווית, קו אלכסוני","הקו דיאגונל עובר אלכסוני בריבוע"]},{"e":"diagram","h":"דיאגרמה","a":["דיאגראם - ציור תרשים, דיאגרמה מסבירה","הדיאגראם הוא כל תרשים תאור"]},{"e":"dialect","h":"ניב","a":["דיאלקט - דבר לקט, ניב של דיבור מקומי","כל אדם דיאלקט קט, בעל ניב שלו"]},{"e":"dialogue","h":"שיחה","a":["דיאלוג - דו שיחה ודיבור בין שניים","הדיאלוג הוא שיחה בין דו אנשים"]},{"e":"diameter","h":"קוטר","a":["דיאמטר - קוטר מודד קוטר העיגול","קוטר הדיאמטר עובר במרכז"]},{"e":"dictate","h":"להכתיב","a":["דיקטט - הכתיב פקודה, דיקטט צו","המנהל דיקטט את הכתב, הכתיב הכל"]},{"e":"diction","h":"דיקציה","a":["דיקשן - דיקציה הוא סגנון הדיבור","בדיקשן טוב תדבר בסגנון מושלם"]},{"e":"dictum","h":"אמרה","a":["דיקטם - דיקטום אמרה חכמה של חכם","זקן החכם דיקטום גדול כל אמרה"]},{"e":"didactic","h":"חינוכי","a":["דידאקטיק - דידקט לשון חינוך וזה חינוכי","השיעור דידקטי, חינוכי וממלא תפקידו"]},{"e":"die","h":"למות","a":["דיי - יום סוף חיים, מת ומת יום","כל דיי יום הוא יום למות"]},{"e":"differ","h":"להיות שונה","a":["דיפר - שונות וחוקים שונים, שניים סכומים","הם דיפרו כי היו שונים זה מזה"]},{"e":"difficult","h":"קשה","a":["דיפיקלט - קשה מאד דיוק קלוט קשה","זה דיפיקלט מאוד, קשה מאד מאד"]},{"e":"diffident","h":"ביישני","a":["דיפידנט - ביישני וביטחון חלוש, דיפ-דן","הילד דיפידנט ביישני וחרד מאד"]},{"e":"diffuse","h":"פזור","a":["דיפיוז - פזור בכל מקום, ראייה קלה","העשן דיפיוז פזור בכל החדר"]},{"e":"digest","h":"לעכל","a":["דיג'סט - עיכול במעיים ודעכול מרובה","הטעם דיג'סט אכל ועכל במהדרין"]}];
